import { createServer, request } from "node:http";
import { connect } from "node:net";
import { afterEach, beforeAll, afterAll, describe, expect, it, vi } from "vitest";
import { browserUrl, createBrowserProxy, isPublicAddress, resolveBrowserHost } from "../src/core/browser/network.ts";
import { boundedBrowserText, BrowserSession } from "../src/core/browser/runtime.ts";
import { BrowserParams } from "../src/core/browser/schema.ts";
import { gateToolCall, registerApprovalHandler, resetAllPermissionContexts, setPermissionMode } from "../src/core/permissions.ts";
import { resolveChildExcludeTools } from "../src/builtin-extensions/pi-subagents/src/runs/shared/child-tools.ts";

const text = (result: Awaited<ReturnType<BrowserSession["run"]>>) => result.content.filter((part) => part.type === "text").map((part) => part.text).join("\n");

afterEach(() => {
	resetAllPermissionContexts();
	registerApprovalHandler(undefined);
});

describe("browser policy and contract", () => {
	it.each(["127.0.0.1", "0.0.0.0", "10.0.0.1", "172.16.0.1", "192.168.1.1", "169.254.169.254", "100.64.1.1", "224.0.0.1", "::1", "::ffff:127.0.0.1", "fc00::1", "fe80::1", "2001:db8::1", "2002:7f00:1::", "64:ff9b::7f00:1"])("rejects reserved address %s", (address) => {
		expect(isPublicAddress(address)).toBe(false);
	});
	it("permits public addresses and rejects malformed URLs", () => {
		expect(isPublicAddress("8.8.8.8")).toBe(true);
		expect(isPublicAddress("2606:4700:4700::1111")).toBe(true);
		for (const url of ["file:///tmp/test", "data:text/html,x", "javascript:alert(1)", "https://user:pass@example.com"]) expect(() => browserUrl(url)).toThrow();
	});
	it("normalizes obfuscated IPs and resolves localhost before enforcing policy", async () => {
		expect(browserUrl("http://2130706433").hostname).toBe("127.0.0.1");
		await expect(resolveBrowserHost("localhost", false)).rejects.toThrow("network policy");
		expect(await resolveBrowserHost("127.0.0.1", true)).toBe("127.0.0.1");
	});
	it("caps snapshots and strips terminal controls", () => {
		expect(boundedBrowserText("x\u001b[31m")).not.toContain("\u001b");
		const result = boundedBrowserText("some text\n".repeat(10000));
		expect(result).toContain("truncated");
		expect(Buffer.byteLength(result)).toBeLessThan(16500);
		expect(result.split("\n").length).toBeLessThanOrEqual(301);
	});
	it("has one bounded schema without evaluation or file-transfer parameters", () => {
		expect(BrowserParams.properties.action.enum).toEqual(["navigate", "inspect", "act", "tabs", "screenshot", "close"]);
		expect(Object.keys(BrowserParams.properties)).not.toEqual(expect.arrayContaining(["evaluate", "script", "path", "cookies"]));
		for (const permissions of ["full", "read-only"] as const) expect(resolveChildExcludeTools({ permissions })).not.toContain("browser");
	});
	it("gates interactions through existing modes, while observation stays allowed", async () => {
		for (const mode of ["manual", "plan", "auto", "yolo"] as const) {
			setPermissionMode(mode);
			for (const action of ["navigate", "inspect", "screenshot", "tabs", "close"]) expect(await gateToolCall("browser", { action }, process.cwd())).toBeUndefined();
			const result = await gateToolCall("browser", { action: "act", interaction: "click", name: "Submit" }, process.cwd());
			expect(Boolean(result?.block)).toBe(mode === "manual" || mode === "plan");
		}
		setPermissionMode("manual");
		const approval = vi.fn(async () => "once" as const);
		registerApprovalHandler(approval);
		expect(await gateToolCall("browser", { action: "act", interaction: "click", name: "Submit" }, process.cwd())).toBeUndefined();
		expect(approval).toHaveBeenCalledWith(expect.objectContaining({ action: "browser", detail: expect.stringContaining("Submit") }));
	});
	it("blocks HTTP subrequests and HTTPS tunnels to private destinations at the proxy", async () => {
		const proxy = await createBrowserProxy(false);
		try {
			const status = await new Promise<number | undefined>((resolve, reject) => {
				const req = request(proxy.url, { path: "http://127.0.0.1:12345/private" }, (response) => { response.resume(); resolve(response.statusCode); });
				req.on("error", reject); req.end();
			});
			expect(status).toBe(403);
			const response = await new Promise<string>((resolve, reject) => {
				const url = new URL(proxy.url);
				const socket = connect(Number(url.port), url.hostname, () => socket.write("CONNECT [::1]:443 HTTP/1.1\r\nHost: [::1]:443\r\n\r\n"));
				socket.once("data", (chunk) => { resolve(chunk.toString()); socket.destroy(); });
				socket.on("error", reject);
			});
			expect(response).toContain("403");
		} finally { await proxy.close(); }
	});
});

describe.skipIf(!process.env.PLAYWRIGHT_BROWSERS_PATH)("actual Chromium fixture", () => {
	const sessions: BrowserSession[] = [];
	let url: string;
	const server = createServer((req, res) => {
		if (req.url === "/slow") return;
		if (req.url === "/redirect") { res.writeHead(302, { location: "/" }).end(); return; }
		if (req.url === "/download") { res.writeHead(200, { "content-disposition": 'attachment; filename="no.txt"' }).end("no"); return; }
		res.setHeader("content-type", "text/html");
		res.end(`<!doctype html><title>Fixture</title><h1>Initial</h1>
