import { execFileSync } from "node:child_process";
import { readFileSync } from "node:fs";
const credential = execFileSync("git", ["credential", "fill"], { input: "protocol=https\nhost=github.com\n\n", encoding: "utf8", stdio: ["pipe", "pipe", "ignore"], env: { ...process.env, GIT_TERMINAL_PROMPT: "0" } });
const token = credential.split(/\r?\n/).find((line) => line.startsWith("password="))?.slice(9);
if (!token) throw new Error("GitHub credential unavailable");
const headers = { Authorization: `Bearer ${token}`, Accept: "application/vnd.github+json", "X-GitHub-Api-Version": "2022-11-28", "Content-Type": "application/json" };
const api = "https://api.github.com/repos/ashx-j/lunR/pulls";
const response = await fetch(`${api}?state=all&head=ashx-j:feat/optional-headless-browser`, { headers });
if (!response.ok) throw new Error(`GitHub list failed: ${response.status}`);
const existing = await response.json();
console.log(JSON.stringify(existing.map((pr) => ({ number: pr.number, url: pr.html_url, state: pr.state })), null, 2));
if (process.argv.includes("--create") && !existing.length) {
	const result = await fetch(api, { method: "POST", headers, body: JSON.stringify({ title: "feat: add an opt-in browser for JavaScript pages", head: "feat/optional-headless-browser", base: "master", draft: false, body: readFileSync(new URL("./browser-pr-body.md", import.meta.url), "utf8") }) });
	if (!result.ok) throw new Error(`GitHub create failed: ${result.status} ${await result.text()}`);
	const pr = await result.json();
	console.log(JSON.stringify({ number: pr.number, url: pr.html_url, state: pr.state, commit: pr.head.sha }, null, 2));
}
